// ── Helpers (shared with the HTML preview so both sides agree) ─────────────────
/** Address object to ordered display lines (street, city/state/zip, country). */
export function formatAddress(obj) {
  if (!obj) return [];
  const lines = [];
  if (obj.street_address) lines.push(obj.street_address);
  const cityLine = [obj.city, obj.state_province, obj.postal_code].filter(Boolean).join(', ');
  if (cityLine) lines.push(cityLine);
  if (obj.country) lines.push(obj.country);
  return lines;
}

export function truncate(text, max) {
  if (!text || text.length <= max) return text;
  return text.slice(0, max).trimEnd() + '…';
}

function capKey(k) {
  return k.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
}

export function fmtAddrDetail(a) {
  if (a.fields && Object.keys(a.fields).length > 0) {
    return Object.entries(a.fields).filter(([, v]) => v)
      .map(([k, v]) => `${capKey(k)}: ${v}`).join(', ');
  }
  return a.address || '';
}

export function fmtAddrLines(a) {
  if (a.fields && Object.keys(a.fields).length > 0) {
    return Object.entries(a.fields).filter(([, v]) => v)
      .map(([k, v]) => `${capKey(k)}: ${v}`);
  }
  return [a.address || ''];
}

/**
 * The remit-to detail an invoice was ISSUED with, as an address array, or null if it has none.
 *
 * @security `platform_payment_addresses` is the
 *           live remit-to row and an admin at AAL2 may change it, which is the intended
 *           function of the role. What was not intended is that a re-render of an already
 *           issued invoice then printed the NEW destination: the snapshot was consulted only
 *           when the live read came back empty, so under every ordinary condition the control
 *           yielded to the value it exists to overrule. Present snapshot wins, full stop.
 * @gotcha two shapes, because the readers were written for the second one and nothing ever
 *         wrote either. An ARRAY is the shape `generateAndUploadIssuedInvoice` stamps, and is
 *         the whole deduped set as rendered. A single OBJECT is the older hand-authored shape
 *         (`method`/`account_type` plus `detail`/`notes`) and normalises to one address.
 * @param {object[]|object|null|undefined} snapshot `invoices.payment_details_snapshot`
 * @returns {object[]|null} address rows, or null when the invoice carries no snapshot
 */
export function snapshotAddresses(snapshot) {
  if (!snapshot) return null;
  if (Array.isArray(snapshot)) return snapshot.length ? snapshot : null;
  const method = snapshot.method || snapshot.account_type || '';
  const address = snapshot.detail || snapshot.notes || '';
  if (!method && !address) return null;
  return [{ method, address, is_preferred: false }];
}

/** Drop duplicate payment addresses keyed on method + formatted detail. */
export function dedupePaymentAddresses(addresses) {
  const seen = new Set();
  return (addresses || []).filter(a => {
    const key = `${(a.method || '').toLowerCase()}:${fmtAddrDetail(a).toLowerCase()}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

/**
 * Deliverables to invoice line items.
 * @gotcha music agencies render one row per deliverable (track metadata matters);
 *         every other agency groups by platform and sums quantity. Falls back to a
 *         single generic "Sponsored post" row when there are no deliverables.
 */
export function buildLineItems(deliverables, isMusicAgency, musicMap) {
  if (!deliverables?.length) {
    return [{ platform: 'Social Media', typeName: 'Sponsored post', qty: 1, postCount: 1, artistName: null, trackName: null, isBundle: false }];
  }
  if (isMusicAgency) {
    return deliverables.map(d => {
      const meta = d.music_url ? (musicMap?.[extractTikTokMusicId(d.music_url) || d.music_url] || {}) : {};
      return {
        platform:   d.platform?.name || 'Social Media',
        typeName:   d.type?.name || 'Sponsored post',
        qty:        d.quantity || 1,
        postCount:  d.quantity || 1,
        artistName: meta.artist || null,
        trackName:  meta.track  || null,
        isBundle:   (d.type?.name || '').toLowerCase().includes('bundle'),
      };
    });
  }
  const groups = {};
  for (const d of deliverables) {
    const p = d.platform?.name || 'Social Media';
    if (!groups[p]) groups[p] = { qty: 0, types: new Set() };
    groups[p].qty += (d.quantity || 1);
    if (d.type?.name) groups[p].types.add(d.type.name);
  }
  return Object.entries(groups).map(([platform, info]) => {
    const typeName = [...info.types].join(', ') || 'Sponsored post';
    const isBundle = typeName.toLowerCase().includes('bundle');
    return { platform, typeName, qty: isBundle ? 1 : info.qty, postCount: info.qty, artistName: null, trackName: null, isBundle };
  });
}

export function fmtLineItemSub(item) {
  const base = item.isBundle
    ? `${item.typeName} of ${item.postCount} posts`
    : `${item.postCount}× ${item.typeName}`;
  if (item.artistName || item.trackName) {
    const track = [item.artistName, item.trackName].filter(Boolean).join(' — ');
    return `${base}  ·  ${track}`;
  }
  return base;
}

// ── PDF pill badge ────────────────────────────────────────────────────────────
function PdfPill({ platform }) {
  const key   = (platform || '').toLowerCase();
  const color = PILL_COLORS[key] || PILL_COLORS.multi;
  return (
    <View style={[s.pdfPill, { backgroundColor: color.bg }]}>
      <Text style={[s.pdfPillText, { color: color.text }]}>{platform?.toUpperCase()}</Text>
    </View>
  );
}

/**
 * Turn a fetched `{ row, invoice, data }` model into the fields an invoice
 * document prints.
 *
 * Both surfaces render THIS component through this one derivation, which is what stops the
 * stored PDF drifting from the approved preview. It lives here rather than in
 * `utils/invoicePdfModel.js` because it is built from six helpers this file exports.
 *
 * @param {object} model `{ row, invoice, data }` from `utils/invoicePdfModel.js`.
 * @returns {object} every field both surfaces derive, plus the members of `data`
 *          they read further down, so a caller destructures once.
 *
 * @gotcha `invoice` is optional-chained throughout: an empty shell beats a generator that
 *         throws mid-render.
 * @gotcha returns the RAW `invoice_number`. The modal's placeholder for an unnumbered draft
 *         stays at the modal: a stored PDF must never print a dash where its number goes.
 * @gotcha paging is NOT here: it is the document's concern and the preview is single-page.
 */
export function buildInvoiceFields({ row, invoice, data }) {
  const {
    agency, sender, deliverables, musicMap = {}, paymentAddresses, platformAccts = [],
  } = data;

  const inKind = isInKind(invoice?.is_in_kind);
  const invoiceDate = invoice?.invoice_date || null;
  const dueDate = invoice?.due_date || null;
  const amount = inKind
    ? (invoice?.in_kind_value ?? invoice?.invoice_amount ?? row.contracted_rate ?? 0)
    : (invoice?.invoice_amount ?? row.contracted_rate ?? 0);
  const amountPaid = invoice?.amount_paid ?? 0;
  const campaignName = row.brand_name || row.campaign_name || '';
  const isMusicAgency = !!(agency?.agency_type?.name?.toLowerCase().includes('music'));
  const authoredTerms = (agency?.payment_term?.invoice_text || '').split('\n').filter((l) => l.trim());

  return {
    agency, sender, deliverables, musicMap, paymentAddresses, platformAccts,

    inKind,
    invoiceNumber: invoice?.invoice_number,
    invoiceDate,
    dueDate,
    amount,
    inKindDesc: inKind ? (invoice?.in_kind_description || null) : null,
    isMusicAgency,
    amountPaid,
    balanceDue: amount - amountPaid,

    billToName: agency.billing_name || agency.name || '',
    billToContact: agency.billing_contact_name || agency.contact_name || '',
    billToAddr: formatAddress(agency),

    fromName: sender?.company_name || 'Nysterys Media LLC',
    fromAddr: formatAddress(sender),
    campaignName,
    serviceDesc: invoice?.service_description || campaignName || 'Social media content',
    websiteDisplay: sender?.website ? sender.website.replace(/^https?:\/\//, '') : 'nysterys.com',

    lineItems: buildLineItems(deliverables, isMusicAgency, musicMap),
    termLines: inKind ? IN_KIND_TERMS : (authoredTerms.length > 0 ? authoredTerms : DEFAULT_TERMS),
    //: the snapshot is authoritative when present, not a fallback. Both surfaces read
    // dedupedAddrs from here, so the preview and the stored PDF cannot disagree about it.
    dedupedAddrs: dedupePaymentAddresses(
      snapshotAddresses(invoice?.payment_details_snapshot) ?? paymentAddresses
    ),
  };
}

// ── PDF Document ──────────────────────────────────────────────────────────────
/**
 * The invoice <Document>. Handles cash + in-kind and campaign + reward from one
 * tree; the in-kind branch swaps Amount Due for FMV, the terms block, and the
 * tax-disclosure footer.
 *
 * @param {object} props
 * @param {object} props.row - campaign/reward summary (brand, campaign name, rate)
 * @param {object} props.invoice - the invoices row
 * @param {object} props.data - the bag from utils/invoicePdfModel.js
 * @gotcha the page-1 main header is declared AFTER the body so it paints over the
 *         body's warmWhite background; the fixed continuation header returns null
 *         on page 1. Render props for page numbers must sit on the outer fixed
 *         View, not an inner Text.
 */
export function InvoicePDF({ row, invoice, data }) {
  const {
    agency, sender, platformAccts,
    inKind, invoiceNumber, invoiceDate, dueDate, amount, inKindDesc,
    amountPaid, balanceDue, billToName, billToContact, billToAddr,
    fromName, fromAddr, campaignName, serviceDesc, websiteDisplay,
    lineItems, termLines, dedupedAddrs,
  } = buildInvoiceFields({ row, invoice, data });

  // Paging is the document's own concern; the preview is single-page.
  const bodyItems     = lineItems.slice(0, -1);
  const lastItemIndex = lineItems.length - 1;
  const lastItem      = lineItems[lastItemIndex];
  const paypalAddr   = dedupedAddrs.find(a => /paypal/i.test(a.method));
  const otherAddrs   = dedupedAddrs.filter(a => !/paypal/i.test(a.method));
  let paypalLine = paypalAddr ? fmtAddrDetail(paypalAddr) : '';
  const paypalLabel  = paypalAddr?.is_preferred ? 'PAYPAL (PREFERRED)' : 'PAYPAL';
  const otherMethodLabel = [...new Set(otherAddrs.map(a => a.method))].join(' / ')
    + (otherAddrs.some(a => a.is_preferred) ? ' (PREFERRED)' : '');
  const multiMethod = new Set(otherAddrs.map(a => a.method)).size > 1;
  let achLines = otherAddrs.length > 0
    ? otherAddrs.flatMap(a => {
        const lines = fmtAddrLines(a);
        return multiMethod ? [`${a.method}: ${lines[0]}`, ...lines.slice(1)] : lines;
      }).join('\n')
    : null;
  if (!paypalLine && !achLines && sender?.email) paypalLine = sender.email;

  const hdrMetaRightBase = [
    invoiceNumber ? `NO. ${invoiceNumber}` : null,
    invoiceDate ? `ISSUED ${fmtDate(invoiceDate).toUpperCase()}` : null,
  ].filter(Boolean).join('   ·   ');

  return (
    <Document>
      <Page size="LETTER" style={s.page}>

        {/* Continuation header: render prop must be on the outer fixed View, not on inner Text.
            Returns null on page 1 (main header covers this slot); shows on page 2+. */}
        <View fixed style={s.contHdr} render={({ pageNumber, totalPages }) =>
          pageNumber === 1 ? null : (
            <View style={s.contHdrInner}>
              <Text style={s.contHdrBrand}>NYS<Text style={s.logoDot}>T</Text>ERYS</Text>
              <Text style={s.contHdrMeta}>{`${inKind ? 'IN-KIND RECORD' : 'INVOICE'}${invoiceNumber ? ` ${invoiceNumber}` : ''}  ·  PAGE ${pageNumber} OF ${totalPages}`}</Text>
            </View>
          )
        } />

        {/* Body */}
        <View style={s.body}>
          {/* Spacer: pushes page-1 content below the main header (~102px - 52px paddingTop - 20px body paddingTop + 16px breathing room) */}
          <View style={{ height: 46 }} />

          {/* Parties */}
          <View style={s.parties}>
            <View style={s.partyCol}>
              <Text style={s.partyLabel}>From</Text>
              <Text style={s.partyName}>{fromName}</Text>
              {fromAddr.map((l, i) => <Text key={i} style={s.partyLine}>{l}</Text>)}
              {sender?.email  ? <Text style={s.partyLineSpaced}>{sender.email}</Text>  : null}
              {sender?.tax_id ? <Text style={s.partyLineSpaced}>EIN: {sender.tax_id}</Text> : null}
            </View>
            <View style={s.partyCol}>
              <Text style={s.partyLabel}>Bill To</Text>
              {billToName    ? <Text style={s.partyName}>{billToName}</Text>    : null}
              {billToContact ? <Text style={s.partyLine}>{billToContact}</Text> : null}
              {billToAddr.map((l, i) => <Text key={i} style={s.partyLine}>{l}</Text>)}
              {!billToAddr.length && agency?.email ? <Text style={s.partyLineSpaced}>{agency.email}</Text> : null}
              {agency?.company_reg_number ? <Text style={s.partyLineSpaced}>Reg: {agency.company_reg_number}</Text> : null}
              {agency?.vat_number         ? <Text style={s.partyLineSpaced}>VAT: {agency.vat_number}</Text>         : null}
            </View>
          </View>

          {/* Amount Due / FMV callout */}
          <View style={s.dueCallout}>
            <View>
              <Text style={s.dueLabel}>{inKind ? 'Fair Market Value' : 'Amount Due'}</Text>
              <Text style={s.dueAmount}>{fmtMoney(amount)}</Text>
            </View>
            <View style={{ alignItems: 'flex-end' }}>
              <Text style={s.dueLabel}>{inKind ? 'Date Received' : 'Due Date'}</Text>
              <Text style={s.dueDate}>{inKind
                ? (invoiceDate ? fmtDate(invoiceDate).toUpperCase() : '—')
                : (dueDate ? fmtDate(dueDate).toUpperCase() : 'TBD')}
              </Text>
              {inKind ? <Text style={s.dueTerms}>No payment due</Text> : null}
            </View>
          </View>

          {/* Reference row */}
          <View style={s.refRow}>
            <View style={s.refCell}>
              <Text style={s.refLabel}>Talent</Text>
              {platformAccts.length > 0
                ? platformAccts.map(acct => (
                    <View key={acct.platform} style={s.handleRow}>
                      <PdfPill platform={acct.platform} />
                      <Text style={s.handleText}>@{acct.username}</Text>
                    </View>
                  ))
                : <Text style={s.refVal}>{row.creator_name ? `@${row.creator_name.replace(/^@/, '').toLowerCase()}` : '—'}</Text>
              }
            </View>
            <View style={s.refCell}>
              <Text style={s.refLabel}>Campaign</Text>
              <Text style={s.refVal}>{campaignName || '—'}</Text>
            </View>
            <View style={[s.refCell, { paddingRight: 0 }]}>
              <Text style={s.refLabel}>Contract / PO</Text>
              <Text style={s.refVal}>{invoice.po_number || '—'}</Text>
            </View>
          </View>

          {/* Table */}
          <View style={s.tableHdrRow}>
            <Text style={s.thDesc}>Description</Text>
            <Text style={s.thQty}>Qty</Text>
            <Text style={s.thRate}>{inKind ? 'FMV' : 'Rate'}</Text>
            <Text style={s.thAmount}>{inKind ? 'FMV' : 'Amount'}</Text>
          </View>

          {/* Body rows: each can independently break to a new page */}
          {bodyItems.map((item, i) => (
            <View key={i} wrap={false} style={[s.tableRow, i % 2 === 1 ? s.tableRowAlt : {}]}>
              <View style={{ flex: 1, paddingRight: 8 }}>
                <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 2 }}>
                  <PdfPill platform={item.platform} />
                  <Text style={s.tdDescMain}>{serviceDesc}</Text>
                </View>
                <Text style={s.tdDescSub}>{inKind && inKindDesc ? truncate(inKindDesc, 120) : fmtLineItemSub(item)}</Text>
              </View>
              <Text style={s.tdQty}>{inKind ? '—' : item.qty}</Text>
              <Text style={s.tdRate}>{i === 0 ? fmtMoney(amount) : '—'}</Text>
              <Text style={s.tdAmount}>{i === 0 ? fmtMoney(amount) : '—'}</Text>
            </View>
          ))}

          {/* Tail: last row + totals + payment info: anchored together, never split */}
          <View wrap={false}>

            <View style={[s.tableRow, lastItemIndex % 2 === 1 ? s.tableRowAlt : {}]}>
              <View style={{ flex: 1, paddingRight: 8 }}>
                <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 2 }}>
                  <PdfPill platform={lastItem.platform} />
                  <Text style={s.tdDescMain}>{serviceDesc}</Text>
                </View>
                <Text style={s.tdDescSub}>{inKind && inKindDesc ? truncate(inKindDesc, 120) : fmtLineItemSub(lastItem)}</Text>
              </View>
              <Text style={s.tdQty}>{inKind ? '—' : lastItem.qty}</Text>
              <Text style={s.tdRate}>{lastItemIndex === 0 ? fmtMoney(amount) : '—'}</Text>
              <Text style={s.tdAmount}>{lastItemIndex === 0 ? fmtMoney(amount) : '—'}</Text>
            </View>

            <View style={s.totalsSection}>
              <View style={s.totalsInner}>
                <View style={s.totalsRow}>
                  <Text style={s.totalsFinalLabel}>{inKind ? 'Fair Market Value' : 'Total'}</Text>
                  <Text style={s.totalsFinalVal}>{fmtMoney(amount)}</Text>
                </View>
                {!inKind && amountPaid > 0 && (
                  <View style={s.balDueBar}>
                    <Text style={s.balDueLabel}>BALANCE DUE</Text>
                    <Text style={s.balDueValue}>{fmtMoney(balanceDue)}</Text>
                  </View>
                )}
              </View>
            </View>

            <View style={s.footerGrid}>
              <View style={s.footerGridCol}>
                {inKind ? (
                  <>
                    <Text style={s.sectionLabel}>TAX DISCLOSURE</Text>
                    <Text style={s.remitSubLabel}>COMPENSATION TYPE</Text>
                    <Text style={s.remitPayable}>Non-cash (in kind)</Text>
                    {inKindDesc ? (
                      <>
                        <Text style={s.remitSubLabel}>ITEMS RECEIVED</Text>
                        <Text style={s.remitText}>{truncate(inKindDesc, 200)}</Text>
                      </>
                    ) : null}
                    <Text style={[s.remitText, { marginTop: 8, color: P.mutedGray }]}>
                      No cash payment is due or expected. FMV is provided for tax reporting purposes only.
                    </Text>
                  </>
                ) : (
                  <>
                    <Text style={s.sectionLabel}>REMIT PAYMENT TO</Text>
                    <Text style={s.remitSubLabel}>PAYABLE TO</Text>
                    <Text style={s.remitPayable}>{fromName}</Text>
                    <View style={s.remitColRow}>
                      {paypalLine ? (
                        <View style={s.remitCol}>
                          <Text style={s.remitSubLabel}>{paypalLabel}</Text>
                          <Text style={s.remitText}>{paypalLine}</Text>
                        </View>
                      ) : null}
                      {achLines ? (
                        <View style={[s.remitCol, { paddingRight: 0 }]}>
                          <Text style={s.remitSubLabel}>{(otherMethodLabel || 'ACH / WIRE').toUpperCase()}</Text>
                          {achLines.split('\n').map((l, i) => <Text key={i} style={s.remitText}>{l}</Text>)}
                        </View>
                      ) : null}
                    </View>
                  </>
                )}
              </View>
              <View style={[s.footerGridCol, { paddingRight: 0 }]}>
                <Text style={s.sectionLabel}>{inKind ? 'IN-KIND TERMS' : 'TERMS'}</Text>
                {termLines.map((l, i) => (
                  <Text key={i} style={s.termItem}>{l}</Text>
                ))}
              </View>
            </View>

          </View>

        </View>

        {/* Page-1 main header: declared after body so it draws over body's warmWhite background */}
        <View style={s.hdrBand}>
          <View style={s.hdrAccent} />
          <View style={s.hdrInner}>
            <View style={s.hdrTop}>
              <Text style={s.logoText}>NYS<Text style={s.logoDot}>T</Text>ERYS</Text>
              <Text style={s.invoiceTitle}>{inKind ? 'IN-KIND RECORD' : 'INVOICE'}</Text>
            </View>
            <View style={s.hdrDivider} />
            <View style={s.hdrMeta}>
              <Text style={s.hdrMetaText}>Creator Management  ·  Brand Partnerships</Text>
              <Text style={s.hdrMetaTextRight}>{hdrMetaRightBase}</Text>
            </View>
          </View>
        </View>

        {/* Footer: render prop on outer View to get pageNumber/totalPages for page counter */}
        <View style={s.footerBand} fixed render={({ pageNumber, totalPages }) => (
          <React.Fragment>
            <View style={s.footerAccent} />
            <View style={s.footerInner}>
              <View>
                <Text style={s.footerBrand}>{fromName.toUpperCase()}</Text>
                <Text style={s.footerSub}>{websiteDisplay}{sender?.email ? `  ·  ${sender.email}` : ''}</Text>
              </View>
              <View>
                <Text style={s.footerThank}>{inKind ? 'TAX RECORD' : 'THANK YOU'}</Text>
                <Text style={s.footerInvNo}>{inKind ? `In-Kind Record${invoiceNumber ? ` ${invoiceNumber}` : ''}` : `Invoice ${invoiceNumber}`}</Text>
                <Text style={s.footerPageNoText}>{`Page ${pageNumber} of ${totalPages}`}</Text>
              </View>
            </View>
          </React.Fragment>
        )} />

      </Page>
    </Document>
  );
}
